/**
 * Returns pixel character and RGB color at (x, y) if within art boundaries.
 */
export function getMorpheusPixel(
  x: number,
  y: number
): { char: string; r: number; g: number; b: number } | null {
  if (x < 0 || x >= MORPHEUS_WIDTH || y < 0 || y >= MORPHEUS_HEIGHT) {
    return null;
  }
  const char = MORPHEUS_CHARS[y]?.[x] || ' ';
  const hex = MORPHEUS_HEX_COLORS[y]?.[x] ?? 0;
  const r = (hex >> 16) & 0xff;
  const g = (hex >> 8) & 0xff;
  const b = hex & 0xff;
  return { char, r, g, b };
}
